int firstAtLeast(const vector<int>& a, int target) {
  int l = 0, r = (int)a.size() - 1;
  while (l < r) {
    int mid = l + (r - l) / 2;
    if (a[mid] < target) l = mid;
    else r = mid;
  }
  return l;
}

